def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(r.count(v) for r in grid))
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny,nx) not in seen:
                        seen.add((ny,nx)); stack.append((ny,nx))
            r0=min(y for y,x in cells); r1=max(y for y,x in cells)
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            border = {(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1)
                      if y in (r0,r1) or x in (c0,c1)}
            if not all(grid[y][x] == color for y,x in border):
                continue
            if any(grid[y][x] != bg for y in range(r0+1,r1) for x in range(c0+1,c1)):
                continue
            fill = 7 if ((r1-r0-1)*(c1-c0-1)) % 2 else 2
            for y in range(r0+1,r1):
                for x in range(c0+1,c1):
                    out[y][x] = fill
    return out
